    #[test]
    fn vue3_compile_script_template_import_usage_handles_member_chains() {
        let mut compiler = SfcCompiler::new();
        let descriptor = compiler.parse(
            "FooBar.vue",
            r#"<script setup lang="ts">
import { Foo, Bar, Baz } from './foo'
</script>
<template>
  <div>{{ Foo.Bar.Baz }}</div>
  <div v-bind="{ ...Foo.Bar.Baz }"></div>
  <div>{{ Foo . Bar . Baz }}</div>
</template>"#,
        );
        let script = compiler.compile_script(&descriptor, SfcScriptCompileOptions::default());

        assert!(script.errors.is_empty(), "{:?}", script.errors);
        assert!(
            script
                .content
                .contains("const __returned__ = { get Foo() { return Foo } }"),
            "content:\n{}\nimports:{:?}",
            script.content,
            script.imports
        );
        assert!(!script.content.contains("get Bar()"));
        assert!(!script.content.contains("get Baz()"));
        assert_eq!(
            script
                .imports
                .get("Foo")
                .map(|binding| binding.is_used_in_template),
            Some(true)
        );
        assert_eq!(
            script
                .imports
                .get("Bar")
                .map(|binding| binding.is_used_in_template),
            Some(false)
        );
        assert_eq!(
            script
                .imports
                .get("Baz")
                .map(|binding| binding.is_used_in_template),
            Some(false)
        );
    }

